from pathlib import Path
from tempfile import TemporaryDirectory
from unittest import TestCase

from scripts.check_requirements_lock import (
    LockPolicyError,
    compare_generated_lock,
    validate_lock,
)


HEADER = """\
# This file was autogenerated by uv via the following command:
#    uv --no-config --no-python-downloads pip compile requirements.in --universal --generate-hashes --python-version 3.11 --exclude-newer 2026-07-28T19:01:14Z --upgrade --only-binary :all: --no-sources --no-cache --default-index https://pypi.org/simple --output-file requirements.txt
"""
HASH_A = "a" * 64
HASH_B = "b" * 64


class RequirementsLockPolicyTests(TestCase):
    def validate(self, direct: str, locked: str) -> tuple[int, int]:
        with TemporaryDirectory() as directory:
            root = Path(directory)
            input_path = root / "requirements.in"
            lock_path = root / "requirements.txt"
            input_path.write_text(direct)
            lock_path.write_text(locked)
            return validate_lock(input_path, lock_path)

    def test_accepts_exact_direct_pin_and_hashed_lock_syntax(self) -> None:
        result = self.validate(
            "mkdocs-material==9.7.7\n",
            HEADER
            + f"""\
dependency==1.0 \\
    --hash=sha256:{HASH_A}
mkdocs-material==9.7.7 \\
    --hash=sha256:{HASH_B}
""",
        )
        self.assertEqual(result, (1, 2))

    def test_rejects_extra_package_against_resolver_output(self) -> None:
        with TemporaryDirectory() as directory:
            root = Path(directory)
            generated_path = root / "generated.txt"
            committed_path = root / "requirements.txt"
            generated_path.write_text(
                HEADER
                + f"""\
mkdocs-material==9.7.7 \\
    --hash=sha256:{HASH_A}
"""
            )
            committed_path.write_text(
                generated_path.read_text()
                + f"""\
unexpected-package==1.0 \\
    --hash=sha256:{HASH_B}
"""
            )
            with self.assertRaisesRegex(
                LockPolicyError, "differs from pinned-resolver output"
            ):
                compare_generated_lock(committed_path, generated_path)

    def test_rejects_unpinned_direct_dependency(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "name==version"):
            self.validate("mkdocs-material>=9\n", HEADER)

    def test_rejects_direct_url(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "URLs"):
            self.validate(
                "package @ https://example.com/package.whl\n",
                HEADER,
            )

    def test_rejects_missing_direct_dependency(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "absent from the lock"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER
                + f"""\
dependency==1.0 \\
    --hash=sha256:{HASH_A}
""",
            )

    def test_rejects_direct_version_mismatch(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "requires 9.7.7"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER
                + f"""\
mkdocs-material==9.7.6 \\
    --hash=sha256:{HASH_A}
""",
            )

    def test_rejects_unhashed_locked_dependency(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "has no SHA-256"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER + "mkdocs-material==9.7.7 \\\n",
            )

    def test_rejects_forbidden_index_option(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "indexes"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER
                + "--extra-index-url https://example.com/simple\n"
                + f"""\
mkdocs-material==9.7.7 \\
    --hash=sha256:{HASH_A}
""",
            )

    def test_rejects_malformed_hash(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "unexpected lock content"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER
                + """\
mkdocs-material==9.7.7 \\
    --hash=sha256:not-a-hash
""",
            )

    def test_rejects_duplicate_locked_dependency(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "duplicate locked"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                HEADER
                + f"""\
mkdocs-material==9.7.7 \\
    --hash=sha256:{HASH_A}
mkdocs_material==9.7.7 \\
    --hash=sha256:{HASH_B}
""",
            )

    def test_rejects_non_deterministic_header(self) -> None:
        with self.assertRaisesRegex(LockPolicyError, "generated header"):
            self.validate(
                "mkdocs-material==9.7.7\n",
                f"""\
mkdocs-material==9.7.7 \\
    --hash=sha256:{HASH_A}
""",
            )
